import{z as l,x as s,o as e,c as d,q as t,j as B,D as a,d as r,s as A,S as i,b as n}from"./chunks/framework.C8m1ZpeB.js";const T=JSON.parse('{"title":"交通与区位","description":"","frontmatter":{"title":"交通与区位","date":"2026-09-18T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/ur-transport-location.md","filePath":"econ/ur-transport-location.md","lastUpdated":1791413859000}'),p={name:"econ/ur-transport-location.md"};function c(m,E,D,u,h,F){const o=s("Mermaid");return e(),d("div",null,[E[2]||(E[2]=t('<h1 id="交通与区位" tabindex="-1">交通与区位 <a class="header-anchor" href="#交通与区位" aria-label="Permalink to &quot;交通与区位&quot;">​</a></h1><div class="epigraph"><p>高峰期的排队，是用零票价配给稀缺路面；道路不缺车道，缺的是价格。</p><footer>—— 据 Pigou, The Economics of Welfare, 1920；Vickrey, Congestion Theory and Transport Investment, American Economic Review 1969；Duranton and Turner, The Fundamental Law of Road Congestion, American Economic Review 2011 整理</footer></div><p><a href="/econ/ur-housing">上一课</a>把房子写成耐用资产，把供给弹性立成关键参数；本课处理另一个参数——通勤成本 \\(t\\)——并把它变成政策变量：收费、扩容、公交，以及为什么修路常常治不了堵。第二课问 \\(t\\) 如何排布城市，本课问政策能不能改 \\(t\\)、改了之后谁受益。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>拥堵是教科书级的负外部性：每辆车加进车流，自己算时间，不算自己加给所有后车的时间，私人边际成本低于社会边际成本。<a href="/econ/externality-pigou">外部性与庇古税</a>给过一般语法；缺口在交通的三个特殊性：外部性随流量非线性放大；需求有隐性储备，扩容会把它钓出来；投资与定价在政治上不对称——修路有预算，收费要说服公众。把交通当普通外部性写税，会把这三条特殊性全丢掉。</p><h3 id="瓶颈与排队" tabindex="-1">瓶颈与排队 <a class="header-anchor" href="#瓶颈与排队" aria-label="Permalink to &quot;瓶颈与排队&quot;">​</a></h3><p>定价：按路段边际外部延误收费，费率随流量变化，这是<a href="/econ/peak-load-pricing">峰荷定价</a>在道路上的直译。Vickrey 1969 的瓶颈模型把排队写成排程问题：通勤者有理想到达时刻，早到成本 \\(\\beta\\)、晚到成本 \\(\\gamma\\)、在途成本 \\(\\alpha\\)；无定价的均衡是人人排队，队列恰好把每个人的总成本抹平；最优时变费率让到达率贴着瓶颈容量走，队列消失，被烧掉的排队时间变成财政收入。实证的反面是扩容：Duranton 与 Turner 2011 用美国都市区面板发现，车道里程与车辆行驶里程近乎同比例增长，拥堵指标不降——「道路的基本定律」，容量被诱发需求吃满。</p><p><span class="marginnote">伦敦拥堵费开征于 2003 年，标准费率起初为每日 5 英镑；据伦敦交通局监测，初期区内拥堵下降约三成、车速明显回升，但至 2010 年前后拥堵已回到开征前水平。收费管住了收费口的需求，管不住需求总量与路网施工——基本定律在城市里的注脚。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>机制在第二条曲线上：\\(t\\) 下降，第二课的出价租梯度变平，城市向外摊开；摊开又拉长平均通勤、生成新的拥堵点——交通投资改写的是区位，不只是路况。出行分布与跨城交流强度按<a href="/econ/gravity-model">引力模型</a>的语法随距离衰减，交通改善等价于把距离矩阵整体调小。收费与扩容的比较还要用<a href="/econ/theory-of-second-best">次优理论</a>：当公交定价存在扭曲时，道路单独最优定价不再全局最优。新加坡 1975 年的区域通行证、1998 年的电子道路收费，与斯德哥尔摩 2006 年试行后经公投常态化，是定价落地的三个常引样本。</p>',10)),(e(),B(i,null,{default:a(()=>[A(o,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20TAU%5B%22%E9%80%9A%E5%8B%A4%E6%88%90%E6%9C%AC%20t%22%5D%20--%3E%20GRAD%5B%22%E5%87%BA%E4%BB%B7%E7%A7%9F%E6%A2%AF%E5%BA%A6%E4%B8%8E%E5%9F%8E%E5%B8%82%E5%BD%A2%E7%8A%B6%22%5D%0A%20%20GRAD%20--%3E%20TAU%0A%20%20ROAD%5B%22%E6%89%A9%E5%AE%B9%3A%20%E8%BD%A6%E9%81%93%E5%A2%9E%E5%8A%A0%22%5D%20--%3E%20IND%5B%22%E8%AF%B1%E5%8F%91%E9%9C%80%E6%B1%82%22%5D%0A%20%20IND%20--%3E%20CONG%5B%22%E6%8B%A5%E5%A0%B5%E4%B8%8D%E9%99%8D%22%5D%0A%20%20TOLL%5B%22%E6%97%B6%E5%8F%98%E6%8B%A5%E5%A0%B5%E6%94%B6%E8%B4%B9%22%5D%20--%3E%20QUEUE%5B%22%E6%8E%92%E9%98%9F%E6%B6%88%E5%A4%B1%2C%20%E5%88%B0%E8%BE%BE%E7%8E%87%E8%B4%B4%E5%AE%B9%E9%87%8F%22%5D%0A%20%20TOLL%20--%3E%20REV%5B%22%E6%94%B6%E5%85%A5%3A%20%E8%BF%94%E8%BF%98%E4%B8%8E%E5%85%AC%E4%BA%A4%22%5D%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[r(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=n("h2",{id:"机制",tabindex:"-1"},[r("机制 "),n("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=n("p",null,"读这个题的次序是：先辨外部性的形状，再选工具。延误外部性随流量增长，所以费率应该是时变的；排队是把稀缺容量配给先到者的机制，本身不产生任何价值，收费只是把排队时间换个口袋。诱发需求提醒容量是被区位内生决定的：路网扩张与土地开发互为因果，把拥堵当成单纯工程问题，会把投资变成位移拥堵的竞赛。",-1)),(e(),B(i,null,{default:a(()=>[A(o,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20CAP%5B%22%E7%93%B6%E9%A2%88%E5%AE%B9%E9%87%8F%E5%9B%BA%E5%AE%9A%22%5D%20--%3E%20NOFEE%5B%22%E9%9B%B6%E7%A5%A8%E4%BB%B7%EF%BC%9A%E5%85%88%E5%88%B0%E5%85%88%E5%BE%97%22%5D%0A%20%20NOFEE%20--%3E%20Q%5B%22%E9%80%9A%E5%8B%A4%E8%80%85%E6%8F%90%E5%89%8D%E5%87%BA%E5%8F%91%E6%8A%A2%E6%97%B6%E5%88%BB%22%5D%0A%20%20Q%20--%3E%20BURN%5B%22%E6%8E%92%E6%88%90%E9%95%BF%E9%BE%99%EF%BC%9A%E6%97%B6%E9%97%B4%E8%A2%AB%E7%BA%AF%E7%83%A7%E6%8E%89%22%5D%0A%20%20FEE%5B%22%E6%97%B6%E5%8F%98%E6%94%B6%E8%B4%B9%EF%BC%9A%E8%B4%B9%E7%8E%87%E9%9A%8F%E6%8B%A5%E6%8C%A4%E4%B8%8A%E5%8D%87%22%5D%20--%3E%20SCHED%5B%22%E9%80%9A%E5%8B%A4%E8%80%85%E9%94%99%E5%B3%B0%E5%87%BA%E5%8F%91%22%5D%0A%20%20SCHED%20--%3E%20FLAT%5B%22%E5%88%B0%E8%BE%BE%E7%8E%87%E8%B4%B4%E7%9D%80%E5%AE%B9%E9%87%8F%E8%B5%B0%22%5D%0A%20%20FLAT%20--%3E%20NOQ%5B%22%E9%98%9F%E5%88%97%E6%B6%88%E5%A4%B1%22%5D%0A%20%20NOQ%20--%3E%20POCK%5B%22%E7%83%A7%E6%8E%89%E7%9A%84%E6%8E%92%E9%98%9F%E6%97%B6%E9%97%B4%E5%8F%98%E6%88%90%E8%B4%A2%E6%94%BF%E6%94%B6%E5%85%A5%22%5D%0A%20%20POCK%20--%3E%20USE%5B%22%E8%BF%94%E8%BF%98%E6%88%96%E6%8A%95%E5%85%AC%E4%BA%A4%EF%BC%9A%E5%88%86%E9%85%8D%E9%9D%A2%E9%85%8D%E5%A5%97%22%5D%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[r(" Loading... ",-1)])]),_:1})),E[5]||(E[5]=t('<p><span class="marginnote">「负外部性」翻译成堵车的话：我加进车流，后面每辆车都慢几秒——这几秒记在我自己账上是零，记在全社会账上是真实损失。拥堵费做的事，就是把我加给别人「的耽误」标上价格收回来，让私人成本追上社会成本。</span></p><p><span class="marginnote">数字实例（诱发需求）：双向 4 车道扩成 8 车道，通行能力翻倍；Duranton–Turner 的发现是，几年后车流量也从每天 10 万辆涨到接近 20 万辆——车速基本没变。路没有变快，只是装下了更多原本被堵「劝退」的车。</span></p><p><span class="marginnote">直觉类比：零票价的道路像免费发放的限量面包——大家凌晨排队，队本身就是「价格」，只是用时间支付。拥堵费把「用时间付」改成「用钱付」：排队消失，同样的稀缺由钱配给，时间转入财政口袋再返还。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>定价的分配面必须写进方案：高费率对低收入通勤者负担更重，收入返还与公交改善是配套而不是施舍。瓶颈模型测的是排队，不测安全、噪声与停车外部性，费率表再精也只覆盖一种边际。公交的覆盖与频率、停车定价、土地出让的区位后果都在课程之外；本课只钉一句话：交通政策的落点不是路况，是 \\(t\\)，而 \\(t\\) 最终写在房租梯度里——下一课把四课攒下的参数拧成国家尺度的空间均衡。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>拥堵是随流量放大的负外部性；庇古定价按边际延误收费。</li><li>瓶颈模型：无定价的均衡是排队，时变收费消队列并产生收入。</li><li>扩容被诱发需求吃满：道路的基本定律（Duranton–Turner 2011）。</li><li>交通改写区位：\\(t\\) 变则梯度变平、城市摊开。</li><li>出处：Pigou 1920；Vickrey, <em>AER</em> 1969；Duranton–Turner, <em>AER</em> 2011；伦敦交通局监测报告（据以整理）。</li></ul>',7))])}const _=l(p,[["render",c]]);export{T as __pageData,_ as default};
